.project-header {
  width: 100%;

  margin-bottom: 1.15rem;
}

.project-number {
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.13em;
  font-weight: 700;
  color: #647565;

  margin-bottom: 0.35rem;
}

.project-title {
  font-size: clamp(1.9rem, 2.5vw, 2.8rem);
  font-weight: 700;
  line-height: 1.12;

