  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(320px, 2fr);
  gap: clamp(3rem, 5vw, 6rem);
  align-items: center;
}

.project-text {
  grid-column: 1;
}

.project-image {
  grid-column: 2;
}


