.research-project.reverse .project-image {
  grid-column: 1;
  grid-row: 1;
}

.research-project.reverse .project-text {
  grid-column: 2;
  grid-row: 1;
}

/* Remove Quarto heading anchor/link icons */
a.anchorjs-link {
  display: none !important;
}

